1	import { HttpClient, HttpErrorResponse } from '@angular/common/http';
2	import { Component, inject, input, output, signal } from '@angular/core';
3	import { firstValueFrom } from 'rxjs';
4	import { Session } from '../../core/session';
5	import { PeriodStore, periodOf } from '../periods/periods';
6	import { NO_RATE, PersonGrade, Rate, RateStore, dueCents, rateOn } from '../rates/rates';
7	
8	/** Where a claim is in its life: DRAFT, then OPEN, then SETTLED; a DRAFT or OPEN claim can be VOID. */
9	export type ClaimStatus = 'DRAFT' | 'OPEN' | 'SETTLED' | 'VOID';
10	
11	/** A status change a claim's buttons ask for. */
12	type ClaimAction = 'open' | 'settle' | 'void';
13	
14	export interface Claim {
15	  id: number;
16	  personId: number;
17	  /** Two decimals, e.g. "10.00". */
18	  amount: string;
19	  date: string;
20	  note: string;
21	  status: ClaimStatus;
22	  /** The claim's number, given when it is opened and kept when it is voided: sheet-wide (1, 2, ...)
23	   *  or, under period numbering, <period>-<n> or X-<n>; null for a claim never opened. */
24	  number: string | null;
25	  /** The due fixed when the claim was settled (two decimals); null until then, or when its grade
26	   *  had no rate to work from. */
27	  settledDue: string | null;
28	  /** The user who opened the claim; null for a claim never opened. */
29	  openedBy: string | null;
30	  /** Whether the person's last statement bound the claim to the figure it had then. */
31	  stated: boolean;
32	  /** The figure the statement bound the claim to (two decimals); null when unbound or it had none. */
33	  statedDue: string | null;
34	  /** The number of the claim a correction (a negative amount) corrects; null when it is not one. */
35	  corrects: string | null;
36	  /** The date the claim's live figures round by (yyyy-mm-dd): its own, or for a correction the date
37	   *  of the claim it corrects. */
38	  roundsBy: string;
39	}
40	
41	/** Whether a claim is a correction: its amount is negative. */
42	export function isCorrection(claim: Claim): boolean {
43	  return cents(claim.amount) < 0;
44	}
45	
46	/** Whether a claim counts toward what is claimed and due: only OPEN and SETTLED ones do. */
47	export function counts(claim: Claim): boolean {
48	  return claim.status === 'OPEN' || claim.status === 'SETTLED';
49	}
50	
51	/** An amount in cents, from the two-decimal string the server sends. */
52	export function cents(amount: string): number {
53	  return Math.round(Number(amount) * 100);
54	}
55	
56	/** What a late charge works from: the sheet's late percent (two decimals), its terms in days and
57	 *  its today; and what a claim's figures round by: the sheet's policy date (blank for its today). */
58	export interface Late {
59	  pct: string;
60	  terms: number;
61	  today: string | null;
62	  policyDate: string;
63	}
64	
65	/** Whether a claim's live figures round half up: it rounds by a date before the sheet's policy date
66	 *  (its today when the policy date is blank); otherwise they round half to even. */
67	function roundsHalfUp(claim: Claim, late: Late): boolean {
68	  const policy = late.policyDate !== '' ? late.policyDate : late.today;
69	  return policy !== null && claim.roundsBy < policy;
70	}
71	
72	/** A claim's figure in cents: the due fixed when it was settled; otherwise the figure a statement
73	 *  bound it to; otherwise its amount times the rate in force on its date among its grade's rates,
74	 *  raised to the sheet's floor (in cents) unless it is a correction; null when it has no figure. */
75	function figureCents(claim: Claim, rates: Rate[], floor: number, halfUp: boolean): number | null {
76	  if (claim.settledDue !== null) return cents(claim.settledDue);
77	  if (claim.stated) return claim.statedDue === null ? null : cents(claim.statedDue);
78	  const rate = rateOn(rates, claim.date);
79	  if (rate === null) return null;
80	  const due = dueCents(cents(claim.amount), rate, halfUp);
81	  return isCorrection(claim) ? due : Math.max(due, floor);
82	}
83	
84	/** A claim's due in cents: its figure plus its late charge, the late percent of the figure for
85	 *  every full 30 days an OPEN claim is overdue, rounded like a due (a statement never binds the
86	 *  charge; settling freezes it into the settled due; a correction has none); null when it has no
87	 *  figure. */
88	export function claimDueCents(claim: Claim, rates: Rate[], floor: number, late: Late): number | null {
89	  const halfUp = roundsHalfUp(claim, late);
90	  const figure = figureCents(claim, rates, floor, halfUp);
91	  if (figure === null) return null;
92	  const periods = isCorrection(claim) ? 0 : Math.floor(daysOverdue(claim, late) / 30);
93	  return periods > 0 ? figure + dueCents(figure * periods, late.pct, halfUp) : figure;
94	}
95	
96	/** How many days an OPEN claim is past its due-by on the sheet's today; 0 when it is not overdue. */
97	function daysOverdue(claim: Claim, late: Late): number {
98	  if (!overdue(claim, late.terms, late.today) || late.today === null) return 0;
99	  return Math.round((Date.parse(late.today) - Date.parse(dueByOf(claim, late.terms))) / 86_400_000);
100	}
101	
102	/** The date a claim is due by (yyyy-mm-dd): its date plus the terms in days. */
103	export function dueByOf(claim: Claim, terms: number): string {
104	  const [y, m, d] = claim.date.split('-').map(Number);
105	  return new Date(Date.UTC(y, m - 1, d + terms)).toISOString().slice(0, 10);
106	}
107	
108	/** Whether a claim is overdue: it is OPEN and its due-by is before the sheet's today. */
109	export function overdue(claim: Claim, terms: number, today: string | null): boolean {
110	  return claim.status === 'OPEN' && today !== null && dueByOf(claim, terms) < today;
111	}
112	
113	/** Cents shown with two decimals. */
114	export function money(total: number): string {
115	  return (total / 100).toFixed(2);
116	}
117	
118	const PAST: Record<ClaimAction, string> = { open: 'opened', settle: 'settled', void: 'voided' };
119	
120	/** An amount of 0.00 or more with up to two decimals. */
121	export const AMOUNT = /^\d+(\.\d{1,2})?$/;
122	
123	/** A claim's amount: any amount with up to two decimals; a negative one is a correction. */
124	const CLAIM_AMOUNT = /^-?\d+(\.\d{1,2})?$/;
125	
126	/** A claim number a correction names: sheet-wide (1, 2, ...) or within a period (P1-1, X-1). */
127	const NUMBER = /^\S+$/;
128	
129	// A person's claims, newest first, and the one form that adds a claim or, once a claim's editor is
130	// opened, saves its changes.
131	@Component({
132	  selector: 'app-person-claims',
133	  template: `
134	    <form (submit)="submit($event)">
135	      <label [for]="'claim-amount-' + personId()">Amount</label>
136	      <input
137	        [id]="'claim-amount-' + personId()"
138	        data-testid="claim-form-amount"
139	        inputmode="decimal"
140	        [value]="amount()"
141	        (input)="amount.set(value($event)); error.set(null)"
142	      />
143	      <label [for]="'claim-date-' + personId()">Date</label>
144	      <input
145	        [id]="'claim-date-' + personId()"
146	        type="date"
147	        data-testid="claim-form-date"
148	        [value]="date()"
149	        (input)="date.set(value($event)); error.set(null)"
150	      />
151	      <label [for]="'claim-note-' + personId()">Note</label>
152	      <input
153	        [id]="'claim-note-' + personId()"
154	        data-testid="claim-form-note"
155	        [value]="note()"
156	        (input)="note.set(value($event)); error.set(null)"
157	      />
158	      <label [for]="'claim-corrects-' + personId()">Corrects claim no.</label>
159	      <input
160	        [id]="'claim-corrects-' + personId()"
161	        data-testid="claim-form-corrects"
162	        [value]="corrects()"
163	        (input)="corrects.set(value($event)); error.set(null)"
164	      />
165	      <button type="submit" data-testid="claim-form-submit">
166	        {{ editingId() === null ? 'Add claim' : 'Save claim' }}
167	      </button>
168	    </form>
169	    @if (error(); as message) {
170	      <p role="alert" data-testid="claim-form-error">{{ message }}</p>
171	    }
172	    <ul>
173	      @for (c of claims(); track c.id) {
174	        <li [attr.data-testid]="'claim-row-' + c.id">
175	          <input
176	            type="checkbox"
177	            data-testid="claim-select"
178	            [attr.aria-label]="'Select claim ' + c.id"
179	            [checked]="selectedIds().has(c.id)"
180	            (change)="selectedChange.emit({ id: c.id, selected: checked($event) })"
181	          />
182	          <span data-testid="claim-amount">{{ c.amount }}</span>
183	          <span data-testid="claim-date">{{ c.date }}</span>
184	          <span data-testid="claim-note">{{ c.note }}</span>
185	          <span data-testid="claim-due">{{ dueOf(c) }}</span>
186	          <span data-testid="claim-due-by">{{ dueBy(c) }}</span>
187	          <span data-testid="claim-overdue">{{ isOverdue(c) ? 'yes' : 'no' }}</span>
188	          <span data-testid="claim-status">{{ c.status }}</span>
189	          <span data-testid="claim-number">{{ c.number ?? '' }}</span>
